const fs = require('fs');
const { execFileSync } = require('child_process');
const zlib = require('zlib');
const path = require('path');

// docx is a zip, let's use Node's built-in zip support or parse manually
// Node 24 might have unzip support... let's try the child_process approach with jar or busybox
// Actually, let's just parse the zip manually

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// ZIP local file header signature = 0x04034b50
// We need to find and extract word/document.xml

function parseZip(buffer) {
  // Find End of Central Directory
  let eocdOffset = -1;
  for (let i = buffer.length - 22; i >= 0; i--) {
    if (buffer.readUInt32LE(i) === 0x06054b50) {
      eocdOffset = i;
      break;
    }
  }

  const cdOffset = buffer.readUInt32LE(eocdOffset + 16);
  const cdEntries = buffer.readUInt16LE(eocdOffset + 10);

  let offset = cdOffset;
  const entries = [];

  for (let i = 0; i < cdEntries; i++) {
    const sig = buffer.readUInt32LE(offset);
    if (sig !== 0x02014b50) break;

    const compMethod = buffer.readUInt16LE(offset + 10);
    const compSize = buffer.readUInt32LE(offset + 20);
    const uncompSize = buffer.readUInt32LE(offset + 24);
    const nameLen = buffer.readUInt16LE(offset + 28);
    const extraLen = buffer.readUInt16LE(offset + 30);
    const commentLen = buffer.readUInt16LE(offset + 32);
    const localHeaderOffset = buffer.readUInt32LE(offset + 42);
    const name = buffer.toString('utf8', offset + 46, offset + 46 + nameLen);

    entries.push({ name, compMethod, compSize, uncompSize, localHeaderOffset });
    offset += 46 + nameLen + extraLen + commentLen;
  }

  return entries;
}

function extractEntry(buffer, entry) {
  const offset = entry.localHeaderOffset;
  const nameLen = buffer.readUInt16LE(offset + 26);
  const extraLen = buffer.readUInt16LE(offset + 28);
  const dataOffset = offset + 30 + nameLen + extraLen;
  const compData = buffer.subarray(dataOffset, dataOffset + entry.compSize);

  if (entry.compMethod === 0) return compData;
  if (entry.compMethod === 8) return zlib.inflateRawSync(compData);
  throw new Error('Unsupported compression: ' + entry.compMethod);
}

const entries = parseZip(buf);
const docEntry = entries.find(e => e.name === 'word/document.xml');

if (!docEntry) { console.log('No word/document.xml found'); process.exit(1); }

const xml = extractEntry(buf, docEntry).toString('utf8');

// Parse text from the XML
const lines = [];
const paraRegex = /<w:p[ >](.*?)<\/w:p>/gs;
let match;
while ((match = paraRegex.exec(xml)) !== null) {
  const paraXml = match[0];
  const textRegex = /<w:t[^>]*>(.*?)<\/w:t>/gs;
  let texts = [];
  let tMatch;
  while ((tMatch = textRegex.exec(paraXml)) !== null) {
    texts.push(tMatch[1]);
  }
  lines.push(texts.join(''));
}

console.log(lines.join('\n'));
"
